function analyzeSalesData(data) {
    // Temizlik
    const categoryAvg = {};
    data.forEach(row => {
        if (row.price > 0) {
            if (!categoryAvg[row.category]) categoryAvg[row.category] = { sum: 0, count: 0 };
            categoryAvg[row.category].sum += row.price;
            categoryAvg[row.category].count++;
        }
    });
    data.forEach(row => {
        if (!row.price && categoryAvg[row.category]) {
            row.price = categoryAvg[row.category].sum / categoryAvg[row.category].count;
        }
    });
    const ratings = data.filter(r => r.rating).map(r => r.rating).sort((a,b) => a-b);
    const medianRating = ratings[Math.floor(ratings.length / 2)];
    data.forEach(r => { if (!r.rating) r.rating = medianRating; });
    data = data.filter(r => r.price > 0 && r.quantity > 0);

    // Feature engineering
    data.forEach(r => {
        r.total = r.price * r.quantity * (1 - (r.discount || 0) / 100);
        r.order_month = new Date(r.order_date).toISOString().slice(0, 7);
        r.is_high_value = r.total > 500;
    });

    const totalRevenue = data.reduce((s, r) => s + r.total, 0);
    return {
        total_revenue: Math.round(totalRevenue * 100) / 100,
        total_orders: data.length,
        avg_order_value: Math.round(totalRevenue / data.length * 100) / 100,
        top_category: Object.entries(data.reduce((acc, r) => { acc[r.category] = (acc[r.category]||0) + r.total; return acc; }, {})).sort((a,b) => b[1]-a[1])[0][0],
        top_city: Object.entries(data.reduce((acc, r) => { acc[r.city] = (acc[r.city]||0) + 1; return acc; }, {})).sort((a,b) => b[1]-a[1])[0][0]
    };
}
